import 'package:flutter/foundation.dart';
import 'package:flutter_soloud/flutter_soloud.dart';

import '../../models/emote.dart';

/// The spell, emote, end-of-game, badge and duel intro sound effects in `assets/sounds/`. Generated by
/// `tool/gen_sfx.py`.
enum SfxSound {
  fireCast('fire_cast'),
  fireExplode('fire_explode'),
  iceCast('ice_cast'),
  iceFreeze('ice_freeze'),
  iceShatter('ice_shatter'),

  /// Buzzes for 0.3 s, then cracks: start it 0.3 s before the bolt hits.
  lightningStrike('lightning_strike'),
  lightningZap('lightning_zap'),
  shieldUp('shield_up'),
  shieldBlock('shield_block'),
  shieldBreak('shield_break'),

  /// Pulse at the start, the hit lands 0.32 s later.
  shieldBash('shield_bash'),
  shieldDouble('shield_double'),
  clashStruggle('clash_struggle'),

  // Emotes
  emoteHallo('emote_hallo'),
  emoteHaha('emote_haha'),
  emoteBoos('emote_boos'),
  emoteHuilen('emote_huilen'),
  emoteGg('emote_gg'),
  emoteGoed('emote_goed'),

  // End of a game: "de-de-duuu" and "duh, duh, duuuh". Their note timings
  // are mirrored in the result screen animation.
  resultWin('result_win'),
  resultLose('result_lose'),

  /// A badge is unlocked. The big chord lands 0.756 s in, when the medal
  /// lands in the unlock overlay.
  badgeUnlock('badge_unlock'),

  /// The "VS" intro before a duel: the slam lands 0.36 s in and "VS"
  /// 0.58 s in, like the animation in `DuelIntro`.
  duelIntro('duel_intro');

  const SfxSound(this.file);

  final String file;

  String get asset => 'assets/sounds/$file.wav';

  /// The sound of [emote], for both the sender and the other player.
  static SfxSound forEmote(Emote emote) => switch (emote) {
    Emote.hallo => emoteHallo,
    Emote.haha => emoteHaha,
    Emote.boos => emoteBoos,
    Emote.huilen => emoteHuilen,
    Emote.gg => emoteGg,
    Emote.goedGespeeld => emoteGoed,
  };
}

/// Plays the spell and emote sound effects.
///
/// Uses SoLoud because it leaves the phone's audio session alone: the
/// voice chat (WebRTC) keeps its call mode on Android and its session on
/// iOS while effects play on top.
///
/// Does nothing until [init] has finished, and when it fails (tests,
/// platforms without audio), so callers never have to check.
class SfxService {
  SfxService._();

  static final instance = SfxService._();

  /// Off in the settings: [play] stays silent. Turning it back on
  /// restarts the engine, so that also fixes sound that went missing.
  bool get enabled => _enabled;
  set enabled(bool value) {
    final turnedOn = value && !_enabled;
    _enabled = value;
    if (turnedOn && _init != null) {
      restart();
    } else if (value) {
      ensureRunning();
    }
  }

  bool _enabled = true;

  final _sources = <SfxSound, AudioSource>{};
  Future<void>? _init;
  DateTime? _lastRetry;

  /// Starts the audio engine and loads every sound. Safe to call twice.
  Future<void> init() => _init ??= _load();

  bool get _ready =>
      _sources.length == SfxSound.values.length &&
      SoLoud.instance.isInitialized;

  /// Starts the engine again when it isn't running, e.g. a failed start,
  /// or Android took the audio device away (call mode, another app).
  /// At most once every few seconds.
  void ensureRunning() {
    // Not started by the app (tests): leave the engine alone.
    if (_init == null || _ready) return;
    final now = DateTime.now();
    if (_lastRetry != null &&
        now.difference(_lastRetry!) < const Duration(seconds: 3)) {
      return;
    }
    _lastRetry = now;
    // Wait for a start that is still running before trying again.
    _init = _init!.then((_) => _ready ? null : _load());
  }

  /// Stops and starts the engine and reloads the sounds. After a video
  /// call Android switches out of call mode, which can leave the engine
  /// playing into an output that no longer exists (silent, no error).
  Future<void> restart() {
    final previous = _init;
    // Not started by the app (tests): nothing to restart.
    if (previous == null) return Future.value();
    return _init = () async {
      try {
        await previous;
      } catch (_) {}
      try {
        await SoLoud.instance.deinitAsync();
      } catch (e) {
        debugPrint('SfxService.deinit: $e');
      }
      _sources.clear();
      await _load();
    }();
  }

  Future<void> _load() async {
    try {
      final soloud = SoLoud.instance;
      if (!soloud.isInitialized) {
        // A new engine: sounds loaded into an old one are gone.
        _sources.clear();
        // Not the low-latency profile: on phones that support it Android
        // then uses AAudio's MMAP path, which goes silent (no error) when
        // WebRTC switches the phone into call mode, and only works on some
        // devices. The normal mixer is a few ms slower, fine for effects.
        await soloud.init(lowLatency: false);
      }
      for (final sound in SfxSound.values) {
        _sources[sound] ??= await soloud.loadAsset(sound.asset);
      }
      debugPrint('SfxService: ${_sources.length} sounds ready');
    } catch (e) {
      debugPrint('SfxService.init failed: $e');
    }
  }

  void play(SfxSound sound, {double volume = 1}) {
    if (!_enabled) return;
    final source = _sources[sound];
    if (source == null || !SoLoud.instance.isInitialized) {
      debugPrint('SfxService: not ready for $sound, restarting');
      ensureRunning();
      return;
    }
    try {
      SoLoud.instance.play(source, volume: volume);
    } catch (e) {
      debugPrint('SfxService.play($sound): $e');
      ensureRunning();
    }
  }
}
